#Requires -Version 7
<#
bossy-generic.tests.ps1: bossy.ps1 on neutral and custom config: setup -Allow (vendor CLI + OS allows generated from the adapters), learn -Read of LESSONS.local.md, file locks (PowerShell and python), board join in a live session (parallel, quiet, -Resume), kit scratch in <runtime>/tmp (cleanup, legacy OS-temp sweep).
Usage: pwsh -NoProfile -File <kit>/tests/bossy-generic.tests.ps1 (or tests/kit-tests.ps1 -Area bossy-generic).
Exit codes: 0 pass · 1 a check failed.
#>
. (Join-Path $PSScriptRoot 'harness.ps1')
$TestKitFiles = @('skills/bossy/adapters/kit_admin.ps1')   # learn -Lesson
$k = New-TestKit bossygen; $O = Join-Path $k 'skills/bossy/bossy.ps1'
# setup -Allow: host + report + OS entries generated, own entries kept, stale generated ones dropped, idempotent
$al = Invoke-PsTest allow @'
$null = . $args[0] 6>$null; $sl = Join-Path $KitConf.Kit 'settings.local.json'
[IO.File]::WriteAllText($sl, '{ "autoMemoryDirectory": "x", "permissions": { "allow": ["Bash(mine *)", "PowerShell(gh pr *)"] } }')
$script:HostType = 'gitlab'; $KitConf.ReportType = 'gdocs'; $KitIsWindows = $true
$r1 = Set-KitAllowList; $s = Get-Content $sl -Raw | ConvertFrom-Json; $a = @($s.permissions.allow)
"gitlab:$($a -contains 'Bash(mine *)' -and $a -notcontains 'PowerShell(gh pr *)' -and $a -contains 'PowerShell(glab mr *)' -and $a -contains 'PowerShell(gws drive files export *)' -and $a -contains 'PowerShell(& *.claude\skills\*)' -and $s.autoMemoryDirectory -eq 'x' -and $r1 -match '^allow: 7 generated entries')"
"same:$(-not (Set-KitAllowList))"
$script:HostType = 'bitbucket'; $KitConf.ReportType = 'markdown'; $KitIsWindows = $false; $null = Set-KitAllowList; $a = @((Get-Content $sl -Raw | ConvertFrom-Json).permissions.allow)
"neutral:$(($a -join '|') -eq 'Bash(mine *)')"
$script:HostType = 'github'; $null = Set-KitAllowList; $a = @((Get-Content $sl -Raw | ConvertFrom-Json).permissions.allow)
"github:$($a -contains 'PowerShell(gh pr *)' -and $a -notcontains 'PowerShell(glab mr *)')"
[IO.File]::WriteAllText($sl, '{ bad'); "badjson:$((Set-KitAllowList) -match 'not valid JSON' -and (Get-Content $sl -Raw) -eq '{ bad')"
'@ @($O)
Expect-Each $al 'setup -Allow: #' 'gitlab', 'same', 'neutral', 'github', 'badjson' -Show 6
$sj = Get-Content (Join-Path $src 'settings.json') -Raw
Expect 'settings.json: no vendor CLI or Windows-path allows (generated by setup -Allow)' ($sj -notmatch '\((glab|gh|gws) ' -and $sj -notmatch '\.claude\\\\skills')
# lessons: learn -Read prints LESSONS.md + LESSONS.local.md; an orgTerms word or -Project goes local, never into LESSONS.md
[IO.File]::WriteAllText((Join-Path $k 'LESSONS.md'), "# Kit lessons`n`n## crafty`n- pub when -> do it (pub why)`n")
[IO.File]::WriteAllText((Join-Path $k 'LESSONS.local.md'), "# local`n`n## crafty`n- loc when -> do it (loc why)`n")
& $J @{ orgTerms = @('Acme') } (Join-Path $k 'skills/crafty/kit.local.json')
$rd = pwsh @np $O learn -Read -Skill crafty | Out-String
$w1 = pwsh @np $O learn -Skill crafty -When 'an Acme host 502' -Do 'retry the job' -Why 'infra' | Out-String
$null = pwsh @np $O learn -Skill crafty -When 'a vendor CLI 404s' -Do 'use its API verb' -Why 'cli drift' -Project shop
$pub = Get-Content (Join-Path $k 'LESSONS.md') -Raw; $loc = Get-Content (Join-Path $k 'LESSONS.local.md') -Raw
Expect "lessons: -Read shows both files; org term / -Project lessons land in LESSONS.local.md ($($w1.Trim()))" ($rd -match 'pub when' -and $rd -match '\(local\)[\s\S]*loc when' -and $w1 -match 'org term: written to LESSONS.local.md' -and $loc -match 'Acme host 502' -and $loc -match 'vendor CLI 404s' -and $pub -notmatch 'Acme|vendor CLI')
Remove-Item (Join-Path $k 'skills/crafty/kit.local.json')
"`n## zz-test`n- a core lesson" | Add-Content (Join-Path $k 'LESSONS.md')
$lr = Invoke-TestScript $O learn -Skill revy -Kind idea -Text 'x'; $r1 = pwsh @np $O learn -Read -Skill zz-test | Out-String; 
Expect 'learn: record + -Read in core' ($lr.out -match 'recorded \(revy/idea\)' -and $r1 -match 'a core lesson')
# board (moved from params.tests for its cap): the same name in a live session 5 min after its beat = a parallel agent
$j3 = pwsh @np $O board join -Agent BY -Run rb | Out-String; $s3 = ($j3 -csplit 'SESSION ')[-1].Split(' ')[0]; $f3 = Join-Path (TkPath $k board) "$s3.json"
$e3 = Read-Json $f3; $e3.holderPid = $PID; $e3.holderStart = & { . (Lib); Get-KitPidStart $PID }; $e3.beat = (Get-Date).AddMinutes(-5).ToString('o'); & $J $e3 $f3
$j4 = pwsh @np $O board join -Agent BY -Run rb | Out-String; $b3 = pwsh @np $O board beat -Session $s3 | Out-String
Expect "board: a same-name agent in a live session is BY-2, no takeover ($j4)" ($j4 -match 'you are BY-2' -and $j4 -notmatch 'TAKEOVER|DUPLICATE' -and $b3 -notmatch 'TAKEN')
$e3 = Read-Json $f3; $e3.beat = (Get-Date).AddMinutes(-40).ToString('o'); $e3 | Add-Member -Force NoteProperty transcript (Join-Path (Kd) 'by.jsonl'); '{}' | Set-Content $e3.transcript; & $J $e3 $f3
$j5 = pwsh @np $O board join -Agent BY -Run rb | Out-String; Expect "board: beat 40 min old, transcript fresh = alive: BY-3" ($j5 -match 'you are BY-3' -and $j5 -notmatch 'TAKEOVER')
# two agents of one session share its holder: a quiet row (beat 45 min, old transcript) is never taken over without -Resume
(Get-Item $e3.transcript).LastWriteTime = (Get-Date).AddMinutes(-45); $e3 = Read-Json $f3; $e3.beat = (Get-Date).AddMinutes(-45).ToString('o'); & $J $e3 $f3
$j6 = pwsh @np $O board join -Agent BY -Run rb | Out-String; $b6 = pwsh @np $O board beat -Session $s3 | Out-String
Expect "board: a quiet row of a live session is not taken over ($j6)" ($j6 -notmatch 'TAKEOVER' -and $j6 -match "QUIET: session $s3" -and $b6 -notmatch 'TAKEN')
$e3 = Read-Json $f3; $e3.beat = (Get-Date).AddMinutes(-45).ToString('o'); & $J $e3 $f3; $j7 = pwsh @np $O board join -Agent BY -Run rb -Resume | Out-String
Expect "board: -Resume without claims takes a quiet row of a live session ($j7)" ($j7 -match "TAKEOVER: replaced session $s3 \(-Resume;")
# kit scratch: <runtime>/tmp for pwsh and python, the gate ledger in the runtime; cleanup ages tmp out and sweeps legacy kit files from the OS temp
$ktParts = & { . (Lib); $kf = New-KitTempFile '.json'; @((Get-KitTemp), $kf, (Test-Path $kf), (Get-KitGateLedger), (Get-KitRuntime)) }
Expect 'kit scratch: Get-KitTemp = <runtime>/tmp, New-KitTempFile makes a file there, the build-gate ledger = <runtime>/work/build-gate (never the OS temp)' (
  $ktParts[0] -eq (Join-Path $ktParts[4] 'tmp') -and (Split-Path $ktParts[1]) -eq $ktParts[0] -and $ktParts[1] -like '*.json' -and $ktParts[2] -and $ktParts[3] -eq (Join-Path $ktParts[4] 'work/build-gate'))
$pyTmp = "$(& $py -X utf8 -c "import sys; sys.path.insert(0, r'$k/skills/bossy'); import kitbag, tempfile; print(tempfile.mkdtemp())")".Trim()
Expect 'kit scratch (python): importing kitbag sends tempfile.* to <runtime>/tmp' ((Split-Path $pyTmp) -eq $ktParts[0] -and (Test-Path $pyTmp))
$osT = [IO.Path]::GetTempPath()   # the harness's own temp stands in for the OS temp
foreach ($p in @("$(TkPath $k tmp -Create)/kit-1-old.tmp", "$osT/kit-legacy-z/a.txt", "$osT/kit-legacy-z", "$osT/claude-build-gate")) { if (-not (Test-Path $p)) { New-Item -Force -ItemType $(if ($p -match '\.\w+$') { 'File' } else { 'Directory' }) $p | Out-Null }; (Get-Item $p).LastWriteTime = (Get-Date).AddDays(-2) }
New-Item -Force -ItemType Directory "$osT/kit-fresh-z" | Out-Null
$cd = pwsh @np $O cleanup -DryRun -WorktreeRoot (Join-Path (Kd) 'no-wt') 2>&1 | Out-String
Expect 'cleanup: kit scratch (<runtime>/tmp) ages out at 24 h; the OS temp only loses kit leftovers idle 24 h (kit-*, the old gate ledger)' ($cd -match '1 x\s+tmp > 24 h .*kit-1-old\.tmp' -and
  $cd -match '2 x\s+kit leftover in the OS temp \(legacy\)')   # kit-legacy-z + claude-build-gate; kit-fresh-z and the fresh test kit stay
# file locks (lib.ps1 Invoke-KitLocked, kitbag.py locked): old holders waited for, a free lock taken at once, python <-> PowerShell
$lt = Join-Path (Kd) 'lk.json'; $old = { '' | Set-Content "$lt.lock"; (Get-Item "$lt.lock").LastWriteTime = (Get-Date).AddMinutes(-5) }   # a 5-min-old lock
& $old; $fs = [IO.File]::Open("$lt.lock", 'Open', 'Write', 'None')
$lj = Start-ThreadJob { Start-Sleep -Milliseconds 1500; ($using:fs).Dispose(); Remove-Item "$using:lt.lock" }
$lw = & { . (Lib); try { Invoke-KitLocked $lt { 'got' } } catch { "threw: $_" } }; $null = $lj | Wait-Job
Expect 'Invoke-KitLocked: an old lock still held open waits for its holder, never fails fast' ($lw -eq 'got')
& $old; $sw = [Diagnostics.Stopwatch]::StartNew()
$l2 = & { . (Lib); Invoke-KitLocked $lt { 'got' } }; $kf2 = Join-Path (Kd) 'kept.json'; '{}' | Set-Content $kf2; $null = & { . (Lib); Invoke-KitLocked $kf2 { 1 } }; $kept = (Test-Path "$kf2.lock") -and -not (Test-FileLockHeld $kf2)
Expect 'Invoke-KitLocked: an old lock nobody holds is taken at once; its file absent: the lock goes too (a kept file keeps it)' ($l2 -eq 'got' -and $sw.Elapsed.TotalSeconds -lt 10 -and -not (Test-Path "$lt.lock") -and $kept)
# python (kitbag.py locked) and PowerShell lock the same byte of the kept lock file: each waits for the other
$pyf = Join-Path (Kd) 'pylock.py'; Set-Content $pyf "import sys, time`nsys.path.insert(0, r'$(Join-Path $k 'skills/bossy')')`nimport kitbag`nt = time.time()`nwith kitbag.locked(r'$lt'):`n    print(round(time.time() - t, 1), flush=True)`n    time.sleep(float(sys.argv[1]))"
$pyp = Start-Process $py -ArgumentList '-X', 'utf8', $pyf, '2' -PassThru -WindowStyle Hidden; for ($pw = 0; $pw -lt 100 -and -not (Test-FileLockHeld $lt); $pw++) { Start-Sleep -Milliseconds 100 }
$sw.Restart(); $psGot = & { . (Lib); Invoke-KitLocked $lt { 'got' } }; $psWait = $sw.Elapsed.TotalSeconds; $null = $pyp.WaitForExit(10000)
$lbp = Lib; $tj = Start-ThreadJob { . $using:lbp; Invoke-KitLocked $using:lt { Start-Sleep -Milliseconds 1500 } }; for ($pw = 0; $pw -lt 100 -and -not (Test-FileLockHeld $lt); $pw++) { Start-Sleep -Milliseconds 50 }
$pyWait = [double]"$(& $py -X utf8 $pyf 0 | Select-Object -Last 1)"; $null = $tj | Wait-Job
Expect "lock: python waits for a PowerShell holder and the other way round (ps waited $([math]::Round($psWait, 1)) s, python $pyWait s)" ($psGot -eq 'got' -and $psWait -ge 1 -and $pyWait -ge 0.8 -and -not (Test-FileLockHeld $lt))
# board leave with the token lost: -Agent -Run leaves that agent's newest row (two rows: the older stays)
$bdD = TkPath $k board -Create; foreach ($bx in @(@('duo-old', '2026-01-01T10:00:00'), @('duo-new', '2026-01-01T11:00:00'))) { & $J @{ session = $bx[0]; agent = 'duo'; run = 'r8'; status = 'working'; beat = $bx[1]; joined = $bx[1] } (Join-Path $bdD "$($bx[0]).json") }
$blD = pwsh @np $O board leave -Agent duo -Run r8 2>&1 | Out-String
Expect "board leave -Agent -Run: the newest of 2 rows left, the older kept ($($blD.Trim()))" ((Get-Content (Join-Path $bdD 'duo-new.json') -Raw | ConvertFrom-Json).status -eq 'left' -and (Get-Content (Join-Path $bdD 'duo-old.json') -Raw | ConvertFrom-Json).status -ne 'left')
# supervise -Ack: a short flag's kind + who ("BUILDS · HQA") is accepted and hides only that flag; a short text matching no flag is refused
& $J @{ lastFlags = @(@{ level = 'WATCH'; what = "builds 'hq web' failed 3 times in a row"; kind = 'BUILDS'; who = 'HQA'; problem = 'hq web failed 3 times in a row' }) } (TkPath $k supervise-state -Create)
$akS = pwsh @np $O supervise -Ack 'BUILDS · HQA' -Reason t 2>&1 | Out-String; $akN = pwsh @np $O supervise -Ack 'BUILDS · XYZ' 2>&1 | Out-String; $akC = $LASTEXITCODE
$akH = pwsh -NoProfile -Command ". '$O'; `$a = (Get-Content (Get-KitPath supervise-state) -Raw | ConvertFrom-Json -AsHashtable).acks; @(Select-KitFlags @([pscustomobject]@{ level = 'WATCH'; what = 'b1'; kind = 'BUILDS'; who = 'HQA'; problem = 'x failed' }, [pscustomobject]@{ level = 'WATCH'; what = 'b2'; kind = 'BUILDS'; who = 'HQB'; problem = 'y failed' }) `$a (Get-Date) | ForEach-Object what) -join ','"
Expect "supervise -Ack: short kind + who accepted, hides that holder's flag only; an unknown short one refused, exit 2 ($akH)" ($akS -match 'hides 1 flag' -and $akN -match '20\+ characters' -and $akC -eq 2 -and "$akH" -match '^b2,1 acknowledged')
Remove-TestKit $k
Complete-Tests
